/* Inside a copy loop after a positive read count n. */
size_t offset = 0;
while (offset < (size_t)n) {
    ssize_t sent = write(out, buffer + offset, (size_t)n - offset);
    if (sent == -1 && errno == EINTR) continue;
    if (sent <= 0) { /* report error or zero progress; release owned fds */
        break;
    }
    offset += (size_t)sent;
}

