/* Standalone lifetime illustration; compile/link with -pthread. */
#include <pthread.h>
#include <stdio.h>
#include <string.h>
static void *worker(void *argument) {
    int *number = argument; /* the caller keeps this int alive */
    *number += 1;
    return NULL;
}
int main(void) {
    int number = 7;
    pthread_t thread;
    int error = pthread_create(&thread, NULL, worker, &number);
    if (error != 0) {
        fprintf(stderr, "create: %s\n", strerror(error));
        return 1;
    }
    error = pthread_join(thread, NULL);
    if (error != 0) {
        fprintf(stderr, "join: %s\n", strerror(error));
        return 1;
    }
    printf("number=%d\n", number); /* join completed before this read */
    return 0;
}

